command:
Powershell -ExecutionPolicy unrestricted -c "
  $out = @()
  (Get-SmbShare | Where-Object {-not $_.Name.endswith('$')} | Select-Object -property Path) | %{
      $out += New-Object PSObject -Property @{
          Path = $_.Path + '\**\*.lnk'
      }
      $out += New-Object PSObject -Property @{
          Path = $_.Path + '\**\*.url'
      }
      $out += New-Object PSObject -Property @{
          Path = $_.Path + '\**\*.scf'
      }
  }
  $out | ConvertTo-Json
"

powershell.exe -ExecutionPolicy RemoteSigned -NoExit -Command "        & 'C:\Users\liusy238\Miniconda3\condabin\conda.bat' shell.powershell hook | Out-String | Invoke-Expression ; 
