powershell.exe "$assemblies=(\"System\");$source=\"
            using System;
using System.Globalization;
            public static class Hello {
                public static void Main() {
                    var format = CultureInfo.CurrentCulture.DateTimeFormat;
            Console.Write(format.ShortDatePattern + `\"|`\" + format.ShortTimePattern);
                }
            }\";Add-Type -ReferencedAssemblies $assemblies -TypeDefinition $source -Language CSharp;[Hello]::Main()"

